"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["91164"],{50728(e){e.exports=JSON.parse('{"id":"FIN-1003","slug":"taxable-event","term":"Taxable Event","also_known_as":[],"difficulty":"Intermediate","definition":"A taxable event is any transaction or occurrence that creates a tax liability under the law, such as receiving income, selling an asset at a gain or receiving a dividend.","explanation":["Tax is usually triggered by specific events rather than by changes in value alone. Common taxable events include being paid wages, receiving interest or dividends, selling shares or property for more than their cost, receiving certain gifts or inheritances, and withdrawing money from some retirement accounts.","For example, if you buy shares for 5,000 and they rise to 8,000, there is normally no tax while you keep them. Selling them is the taxable event: it turns the 3,000 increase into a realized gain that may be taxed.","Understanding which events are taxable helps with planning. Investors can often choose when to sell, and therefore in which tax year a gain falls. Moving investments between accounts, swapping one fund for another or exchanging one cryptocurrency for another can all be taxable events in some countries, even though no cash is received.","The rules differ by country and by type of asset. Some transfers, such as gifts between spouses or moving assets within tax-advantaged accounts, may be exempt."],"note":"","total":1500,"prev":{"slug":"taxable-account","term":"Taxable Account"},"next":{"slug":"taxable-income","term":"Taxable Income"}}')}}]);